  "onl.tz.butceRakip": ["Bu malın aylık hane bütçesi %1 akçe; %2 rakip satırla paylaşılıyor.", "This good's monthly household budget is %1 akçe; it is shared with %2 competing rows.", "El presupuesto mensual de los hogares para este bien es de %1 akçe; se reparte con %2 filas rivales.", "O orçamento mensal das casas para este bem é de %1 akçe; é partilhado com %2 linhas rivais.", "ميزانية الأسر الشهرية لهذه البضاعة %1 أقجة؛ وتُقسَّم مع %2 من الصفوف المنافسة.", "Месячный бюджет домохозяйств на этот товар — %1 акче; его делят с %2 строками-соперниками."],
  "onl.tz.butceTek": ["Bu malın aylık hane bütçesi %1 akçe; bu ay rakibin yok.", "This good's monthly household budget is %1 akçe; you have no rivals this month.", "El presupuesto mensual de los hogares para este bien es de %1 akçe; este mes no tienes rivales.", "O orçamento mensal das casas para este bem é de %1 akçe; este mês não tem rivais.", "ميزانية الأسر الشهرية لهذه البضاعة %1 أقجة؛ ولا منافس لك هذا الشهر.", "Месячный бюджет домохозяйств на этот товар — %1 акче; в этом месяце соперников нет."],
  "onl.tz.neden.butce": ["Hane bütçesi ancak bu kadarına yetti.", "The household budget only stretched this far.", "El presupuesto de los hogares solo alcanzó para esto.", "O orçamento das casas só deu para isto.", "ميزانية الأسر لم تكفِ إلا لهذا القدر.", "Бюджета домохозяйств хватило лишь на это."],
  "onl.tz.neden.stok": ["Raftaki malın hepsi satıldı.", "All the goods on the shelf sold.", "Se vendió todo lo que había en el estante.", "Tudo o que estava na prateleira foi vendido.", "بيعت كل البضاعة التي على الرف.", "Весь товар с полки продан."],
  "onl.tz.neden.tavan": ["Fiyat halk tavanının üstünde; halk bu fiyata almadı.", "The price is above the townsfolk's cap; they did not buy.", "El precio supera el tope de la gente; no compró.", "O preço está acima do teto do povo; o povo não comprou.", "السعر فوق سقف الأهالي؛ فلم يشتروا.", "Цена выше потолка горожан; они не купили."],
  "onl.tz.neden.rakip": ["Rakip raflar payı paylaştı.", "Rival shelves split the share.", "Los estantes rivales se repartieron la cuota.", "As prateleiras rivais dividiram a parte.", "تقاسمت الرفوف المنافسة الحصة.", "Полки соперников поделили долю."],
  "onl.tz.neden.seviyeTavani": ["Dükkânın seviye tavanına ulaşıldı; seviye arttıkça tavan yükselir.", "The shop's level cap was reached; the cap rises as the level does.", "Se alcanzó el tope de nivel de la tienda; el tope sube con el nivel.", "Atingiu-se o teto de nível da loja; o teto sobe com o nível.", "بلغ الدكان سقف مستواه؛ ويرتفع السقف كلما ارتفع المستوى.", "Достигнут потолок уровня лавки; он растёт вместе с уровнем."],
