  "onl.tz.depo.al": ["Depodan heybeye", "Storeroom to saddlebag", "Del almacén a las alforjas", "Do depósito aos alforges", "من المخزن إلى الخرج", "Со склада в суму"],
  "onl.tz.depo.malSec": ["Heybeden bir mal seç.", "Pick a good from your saddlebag.", "Elige un bien de tus alforjas.", "Escolha um bem dos seus alforges.", "اختر بضاعة من خرجك.", "Выберите товар из сумы."],
  "onl.tz.depo.satirSec": ["Depodan bir mal seç.", "Pick a good from the storeroom.", "Elige un bien del almacén.", "Escolha um bem do depósito.", "اختر بضاعة من المخزن.", "Выберите товар со склада."],
  "onl.tz.depo.heybedeYok": ["Heybende bu kalitede mal kalmadı.", "No goods of this quality are left in your saddlebag.", "No te quedan bienes de esta calidad en las alforjas.", "Já não tem bens desta qualidade nos alforges.", "لم يبقَ في خرجك شيء بهذه الجودة.", "В суме не осталось товара такого качества."],
  "onl.tz.depo.depodaYok": ["Depoda bu mal kalmadı.", "This good is no longer in the storeroom.", "Este bien ya no está en el almacén.", "Este bem já não está no depósito.", "لم تعد هذه البضاعة في المخزن.", "Этого товара на складе больше нет."],
  "onl.tz.depo.kondu": ["%1 %2 depoya kondu.", "%1 %2 put into the storeroom.", "%1 %2 pasaron al almacén.", "%1 %2 foram para o depósito.", "وُضع %1 %2 في المخزن.", "На склад положено: %2 — %1."],
  "onl.tz.depo.alindi": ["%1 %2 heybene alındı.", "%1 %2 taken into your saddlebag.", "%1 %2 pasaron a tus alforjas.", "%1 %2 foram para os seus alforges.", "أُخذ %1 %2 إلى خرجك.", "В суму взято: %2 — %1."],
  "onl.tz.depo.heybeBos": ["Heybende rafa çıkabilecek mal yok.", "You have no goods in your saddlebag that can go on the shelf.", "No tienes en las alforjas bienes que puedan ir al estante.", "Não tem nos alforges bens que possam ir para a prateleira.", "ليس في خرجك بضاعة يمكن وضعها على الرف.", "В суме нет товара, который можно выложить на полку."],
  "onl.tz.depo.heybeBosAtolye": ["Heybende depoya konacak mal yok.", "You have no goods in your saddlebag to put in the storeroom.", "No tienes en las alforjas bienes que llevar al almacén.", "Não tem nos alforges bens para levar ao depósito.", "ليس في خرجك بضاعة تُوضع في المخزن.", "В суме нет товара, который можно положить на склад."],
