  "onl.tz.rafaEklendi": ["%1 %2 rafa kondu.", "%1 %2 put on the shelf.", "%1 %2 pasaron al estante.", "%1 %2 foram para a prateleira.", "وُضع %1 %2 على الرف.", "На полку выложено: %2 — %1."],
  "onl.tz.raftanAlindi": ["%1 %2 depoya döndü.", "%1 %2 returned to the storeroom.", "%1 %2 volvieron al almacén.", "%1 %2 voltaram ao depósito.", "عاد %1 %2 إلى المخزن.", "На склад возвращено: %2 — %1."],
