  // ---- Satın alma (müşteri)
  "onl.tz.malBitti": ["Bu mal tükendi.", "This good is sold out.", "Este bien se agotó.", "Este bem esgotou.", "نفدت هذه البضاعة.", "Этот товар закончился."],
  "onl.tz.akceYetmez": ["%1 akçe gerekiyor; kesende %2 var.", "%1 akçe needed; your purse holds %2.", "Hacen falta %1 akçe; tu bolsa tiene %2.", "São precisos %1 akçe; a sua bolsa tem %2.", "المطلوب %1 أقجة؛ وفي كيسك %2.", "Нужно %1 акче; в кошельке у вас %2."],
  "onl.tz.alindi": ["%1 %2 aldın; %3 akçe ödendi.", "You bought %1 %2; %3 akçe paid.", "Compraste %1 %2; pagaste %3 akçe.", "Comprou %1 %2; pagou %3 akçe.", "اشتريت %1 %2؛ ودُفع %3 أقجة.", "Куплено: %2 — %1; уплачено %3 акче."],
  "onl.tz.vergiNot": ["Tutarın %2 akçesi (%1) beyliğe vergi olarak gitti.", "%2 akçe of the amount (%1) went to the beylik as tax.", "%2 akçe del importe (%1) fueron al beylicato como impuesto.", "%2 akçe do valor (%1) foram para o beylik como imposto.", "ذهب %2 أقجة من المبلغ (%1) إلى الإمارة ضريبةً.", "%2 акче из суммы (%1) ушли бейлику как налог."],
